# microsatellite detection: find runs where a period p (1..12) is highly conserved over >=4 units
def find_period_arrays(periods=range(1,13), min_units=4, min_ident=0.85):
    res=[]
    i=0
    while i < n:
        best=None
        for p in periods:
            # try to extend a tandem array with period p starting at i
            j=i
            # greedily extend while next p-mer matches first p-mer with >=min_ident
            unit=seq[i:i+p]
            if len(unit)<p: break
            k=i
            count=0
            while k+p<=n:
                cand=seq[k:k+p]
                ident=sum(1 for a,b in zip(cand,unit) if a==b)/p
                if ident>=min_ident:
                    count+=1; k+=p
                else:
                    break
            if count>=min_units:
                if best is None or count*p>best[1]:
                    best=(i,count*p,p,count,seq[i:i+min(count*p,120)])
        if best:
            res.append(best)
            i=best[0]+best[1]
        else:
            i+=1
    return res

